/** Explicit local clone upgrade only. Root separately admits the exact review and pins this wrapper and input before invocation. */
import {readFile} from 'node:fs/promises'
import {createPostgresConnection} from '../packages/neuvetra-database/src/hosted'
import {upgradeLocal,type LocalUpgradeGate} from '../tools/staging/m78-upgrade'
import {hostedSourcePins} from '../tools/staging/m78-hosted-database'
import {hash,sha,PROJECT,REVIEWED_MIGRATION_SHA256,check} from '../tools/staging/m78-inventory'
const [inputPath,inputSha]=process.argv.slice(2)
let db:ReturnType<typeof createPostgresConnection>|undefined
try {
 check(inputPath&&inputSha&&/^[a-f0-9]{64}$/.test(inputSha))
 const bytes=await readFile(inputPath);check(sha(bytes)===inputSha,'Input bytes changed')
 const v=JSON.parse(bytes.toString('utf8'))
 check(/^m78_ops_recipe_[a-z0-9_]+$/.test(v.database),'Fresh recipe clone only')
 check(hash(v.sourcePins)===hash(await hostedSourcePins()),'Reviewed source closure changed')
 for(const pin of [v.review,v.restore])check(sha(await readFile(pin.path))===pin.sha256,'Evidence bytes changed')
 const events=(await readFile(v.restore.path,'utf8')).trim().split('\n').map(s=>JSON.parse(s))
 check(events.length===2,'Exactly original successful restore events required')
 const started=events[0],restored=events[1]
 check(started.status==='m78_restore_started'&&started.database===v.database&&started.bundleSha256===restored.bundleSha256,'Original matching restore start required')
 check(Number.isFinite(Date.parse(started.createdAt))&&Number.isFinite(Date.parse(restored.createdAt))&&Date.parse(started.createdAt)<=Date.parse(restored.createdAt),'Original ordered restore timestamps required')
 check(restored.status==='m78_local_application_restored'&&restored.database===v.database,'Original restore success required')
 const gate:LocalUpgradeGate={profile:'neuvetra.m78.local-upgrade-gate.v1',project:PROJECT,database:v.database,createdAt:new Date().toISOString(),operatorId:'/root',reviewerId:'/root/m76_backend',reviewSnapshotSha256:v.review.sha256,migrationSha256:REVIEWED_MIGRATION_SHA256,baselineBundleSha256:restored.bundleSha256,restoreReceiptSha256:sha(JSON.stringify(restored)),baselineInventory:restored.inventory,baselineContent:restored.content,localOnly:true}
 check(/^\.superpowers\/m78-recipe-[a-z0-9_-]+-upgrade\.jsonl$/.test(v.journalPath),'New explicit journal required')
 db=createPostgresConnection(`postgres://supabase_admin@127.0.0.1:55472/${v.database}`,{tls:false,maxConnections:1})
 const receipt=await upgradeLocal(db,gate,restored,v.journalPath)
 console.log(JSON.stringify({status:receipt.status,database:v.database,schemaVersion:receipt.schemaVersion,journalPath:v.journalPath}))
} catch {console.log(JSON.stringify({status:'m78_root_local_upgrade_failed_verify_before_retry'}));process.exitCode=1}
finally{await db?.close()}
